  "code": "import re

def register_device(device_info):
    device_id = device_info.get('device_id')
    firmware_version = device_info.get('firmware_version')
    enabled = device_info.get('enabled', False)
    tags = device_info.get('tags', [])

    # Validate device_id
    if not re.match(r'^[0-9A-F]{12}$', device_id):
        raise ValueError('Invalid device_id format')

    # Validate firmware_version
    if not re.match(r'^v\d{1,3}\.\d{1,3}\.\d{1,3}$', firmware_version):
        raise ValueError('Invalid firmware_version format')

    # Validate tags
    tag_pattern = re.compile(r'^[a-zA-Z0-9_]{1,20}$')
    for tag in tags:
        if not tag_pattern.match(tag):
            raise ValueError('Invalid tag format')

    return f'Registered: {device_id}'"
}
